using ContosoUniversity.Models;
using Xunit;

namespace ContosoUniversity.Tests.Models
{
    public class PersonTests
    {
        [Theory]
        [InlineData("Doe", "John", "Doe, John")]
        [InlineData("Smith", "Jane", "Smith, Jane")]
        [InlineData("O'Brien", "A", "O'Brien, A")]
        public void FullName_CombinesLastAndFirst(string lastName, string firstName, string expected)
        {
            var student = new Student { LastName = lastName, FirstMidName = firstName };

            Assert.Equal(expected, student.FullName);
        }
    }

    public class ErrorViewModelTests
    {
        [Fact]
        public void ShowRequestId_WhenRequestIdIsSet_ReturnsTrue()
        {
            var model = new ErrorViewModel { RequestId = "abc123" };

            Assert.True(model.ShowRequestId);
        }

        [Theory]
        [InlineData(null)]
        [InlineData("")]
        public void ShowRequestId_WhenRequestIdIsNullOrEmpty_ReturnsFalse(string requestId)
        {
            var model = new ErrorViewModel { RequestId = requestId };

            Assert.False(model.ShowRequestId);
        }
    }
}

