using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Mvc;
using System;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class StudentsControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly StudentsController _controller;

        public StudentsControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _controller = new StudentsController(_context);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
        }

        private Student SeedStudent(string first = "John", string last = "Doe", DateTime? enrollDate = null)
        {
            var student = new Student
            {
                FirstMidName = first,
                LastName = last,
                EnrollmentDate = enrollDate ?? new DateTime(2020, 9, 1)
            };
            _context.Students.Add(student);
            _context.SaveChanges();
            return student;
        }

        #region Index

        [Fact]
        public void Index_NoParams_ReturnsViewWithStudents()
        {
            SeedStudent("Alice", "Smith");
            SeedStudent("Bob", "Jones");

            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        [Fact]
        public void Index_DefaultSort_OrdersByLastNameAsc()
        {
            SeedStudent("Alice", "Zimmerman");
            SeedStudent("Bob", "Adams");

            var result = _controller.Index(null, null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Adams", model[0].LastName);
            Assert.Equal("Zimmerman", model[1].LastName);
        }

        [Fact]
        public void Index_NameDescSort_OrdersByLastNameDesc()
        {
            SeedStudent("Alice", "Adams");
            SeedStudent("Bob", "Zimmerman");

            var result = _controller.Index("name_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("Zimmerman", model[0].LastName);
            Assert.Equal("Adams", model[1].LastName);
        }

        [Fact]
        public void Index_DateSort_OrdersByEnrollmentDateAsc()
        {
            SeedStudent("Alice", "A", new DateTime(2021, 1, 1));
            SeedStudent("Bob", "B", new DateTime(2019, 1, 1));

            var result = _controller.Index("Date", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("B", model[0].LastName);
            Assert.Equal("A", model[1].LastName);
        }

        [Fact]
        public void Index_DateDescSort_OrdersByEnrollmentDateDesc()
        {
            SeedStudent("Alice", "A", new DateTime(2019, 1, 1));
            SeedStudent("Bob", "B", new DateTime(2021, 1, 1));

            var result = _controller.Index("date_desc", null, null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Equal("B", model[0].LastName);
        }

        [Fact]
        public void Index_SearchString_FiltersStudents()
        {
            SeedStudent("Alice", "Smith");
            SeedStudent("Bob", "Jones");

            var result = _controller.Index(null, null, "Smith", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Single(model);
            Assert.Equal("Smith", model[0].LastName);
        }

        [Fact]
        public void Index_SearchByFirstName_FiltersStudents()
        {
            SeedStudent("Alice", "Smith");
            SeedStudent("Bob", "Jones");

            var result = _controller.Index(null, null, "Alice", null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Single(model);
            Assert.Equal("Alice", model[0].FirstMidName);
        }

        [Fact]
        public void Index_NewSearch_ResetsToPage1()
        {
            SeedStudent();

            var result = _controller.Index(null, null, "test", null) as ViewResult;

            // When searchString is not null, page should be set to 1
            Assert.NotNull(result);
        }

        [Fact]
        public void Index_NoSearch_UsesCurrentFilter()
        {
            SeedStudent("Test", "User");

            var result = _controller.Index(null, "User", null, null) as ViewResult;
            var model = Assert.IsType<PaginatedList<Student>>(result.Model);

            Assert.Single(model);
        }

        [Fact]
        public void Index_SetsViewBagSortParams()
        {
            var result = _controller.Index(null, null, null, null) as ViewResult;

            Assert.Equal("name_desc", _controller.ViewBag.NameSortParm);
            Assert.Equal("Date", _controller.ViewBag.DateSortParm);
        }

        [Fact]
        public void Index_NameDescSort_SetsNameSortParmEmpty()
        {
            var result = _controller.Index("name_desc", null, null, null) as ViewResult;

            Assert.Equal("", _controller.ViewBag.NameSortParm);
        }

        [Fact]
        public void Index_DateSort_SetsDateSortParmToDateDesc()
        {
            var result = _controller.Index("Date", null, null, null) as ViewResult;

            Assert.Equal("date_desc", _controller.ViewBag.DateSortParm);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithStudent()
        {
            var student = SeedStudent("Alice", "Smith");

            var result = _controller.Details(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Alice", model.FirstMidName);
            Assert.Equal("Smith", model.LastName);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsViewWithDefaultDate()
        {
            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal(DateTime.Today, model.EnrollmentDate);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_ValidStudent_RedirectsToIndex()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Create(student);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Students);
        }

        [Fact]
        public void Create_Post_DefaultDate_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = DateTime.MinValue
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        [Fact]
        public void Create_Post_InvalidDateRange_AddsModelError()
        {
            var student = new Student
            {
                FirstMidName = "New",
                LastName = "Student",
                EnrollmentDate = new DateTime(1750, 1, 1)
            };

            // MinValue triggers the first check, so we won't reach the range check
            // Use a date that's past MinValue but before 1753
            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.False(_controller.ModelState.IsValid);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("LastName", "Required");
            var student = new Student
            {
                FirstMidName = "Test",
                EnrollmentDate = new DateTime(2023, 1, 1)
            };

            var result = _controller.Create(student) as ViewResult;

            Assert.NotNull(result);
            Assert.Equal(student, result.Model);
        }

        #endregion

        #region Edit GET

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = SeedStudent("Edit", "Me");

            var result = _controller.Edit(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Edit", model.FirstMidName);
        }

        #endregion

        #region Edit POST

        [Fact]
        public void Edit_Post_ValidStudent_RedirectsToIndex()
        {
            var student = SeedStudent("Old", "Name");
            _context.Entry(student).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Student
            {
                ID = student.ID,
                FirstMidName = "New",
                LastName = "Name",
                EnrollmentDate = new DateTime(2023, 9, 1)
            };

            var result = _controller.Edit(updated);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_DefaultDate_AddsModelError()
        {
            var updated = new Student
            {
                ID = 1,
                FirstMidName = "New",
                LastName = "Name",
                EnrollmentDate = default(DateTime)
            };

            var result = _controller.Edit(updated) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("EnrollmentDate"));
        }

        #endregion

        #region Delete GET

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Delete(999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithStudent()
        {
            var student = SeedStudent("Delete", "Me");

            var result = _controller.Delete(student.ID) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Student>(result.Model);
            Assert.Equal("Delete", model.FirstMidName);
        }

        #endregion

        #region DeleteConfirmed

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesAndRedirects()
        {
            var student = SeedStudent("Gone", "Soon");

            var result = _controller.DeleteConfirmed(student.ID);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Empty(_context.Students);
        }

        #endregion
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
using ContosoUniversity.Tests.Helpers;
using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using Moq;
using System;
using System.IO;
using System.Linq;
using Xunit;

namespace ContosoUniversity.Tests.Controllers
{
    public class CoursesControllerTests : IDisposable
    {
        private readonly SchoolContext _context;
        private readonly CoursesController _controller;
        private readonly Mock<IWebHostEnvironment> _mockEnv;
        private readonly Mock<ILogger<CoursesController>> _mockLogger;
        private readonly string _tempDir;

        public CoursesControllerTests()
        {
            _context = TestDbContextFactory.Create();
            _mockEnv = new Mock<IWebHostEnvironment>();
            _mockLogger = new Mock<ILogger<CoursesController>>();

            _tempDir = Path.Combine(Path.GetTempPath(), Guid.NewGuid().ToString());
            Directory.CreateDirectory(_tempDir);
            _mockEnv.Setup(e => e.WebRootPath).Returns(_tempDir);
            _mockEnv.Setup(e => e.ContentRootPath).Returns(_tempDir);

            _controller = new CoursesController(_context, _mockEnv.Object, _mockLogger.Object);
        }

        public void Dispose()
        {
            _controller.Dispose();
            _context.Dispose();
            if (Directory.Exists(_tempDir))
            {
                try { Directory.Delete(_tempDir, true); } catch { }
            }
        }

        private Department SeedDepartment(string name = "Engineering")
        {
            var dept = new Department
            {
                Name = name,
                Budget = 100000,
                StartDate = new DateTime(2020, 1, 1)
            };
            _context.Departments.Add(dept);
            _context.SaveChanges();
            return dept;
        }

        private Course SeedCourse(string title = "Physics", int credits = 3, int courseId = 0, Department dept = null)
        {
            dept ??= SeedDepartment();
            var course = new Course
            {
                CourseID = courseId == 0 ? new Random().Next(1000, 9999) : courseId,
                Title = title,
                Credits = credits,
                DepartmentID = dept.DepartmentID
            };
            _context.Courses.Add(course);
            _context.SaveChanges();
            return course;
        }

        #region Index

        [Fact]
        public void Index_ReturnsViewWithCourses()
        {
            var dept = SeedDepartment();
            SeedCourse("Calculus", 4, 1001, dept);
            SeedCourse("Algebra", 3, 1002, dept);

            var result = _controller.Index() as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsAssignableFrom<System.Collections.Generic.List<Course>>(result.Model);
            Assert.Equal(2, model.Count);
        }

        #endregion

        #region Details

        [Fact]
        public void Details_NullId_ReturnsBadRequest()
        {
            var result = _controller.Details(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Details_ValidId_ReturnsViewWithCourse()
        {
            var course = SeedCourse("Chemistry", 3, 2001);

            var result = _controller.Details(2001) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Chemistry", model.Title);
        }

        #endregion

        #region Create GET

        [Fact]
        public void Create_Get_ReturnsViewWithDepartmentSelectList()
        {
            SeedDepartment("Math");

            var result = _controller.Create() as ViewResult;

            Assert.NotNull(result);
            Assert.NotNull(_controller.ViewBag.DepartmentID);
        }

        #endregion

        #region Create POST

        [Fact]
        public void Create_Post_ValidCourse_RedirectsToIndex()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3001,
                Title = "New Course",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var result = _controller.Create(course, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Single(_context.Courses);
        }

        [Fact]
        public void Create_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 3002, Title = "X", Credits = 3 };

            var result = _controller.Create(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        [Fact]
        public void Create_Post_ValidImage_SavesFileAndRedirects()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3003,
                Title = "With Image",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.jpg");
            mockFile.Setup(f => f.Length).Returns(1024);
            mockFile.Setup(f => f.CopyTo(It.IsAny<Stream>()));

            var result = _controller.Create(course, mockFile.Object);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            var saved = _context.Courses.Find(3003);
            Assert.NotNull(saved.TeachingMaterialImagePath);
            Assert.StartsWith("/Uploads/TeachingMaterials/", saved.TeachingMaterialImagePath);
        }

        [Fact]
        public void Create_Post_InvalidFileExtension_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3004,
                Title = "Bad Ext",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("test.exe");
            mockFile.Setup(f => f.Length).Returns(1024);

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Create_Post_FileTooLarge_ReturnsViewWithError()
        {
            var dept = SeedDepartment();
            var course = new Course
            {
                CourseID = 3005,
                Title = "Large File",
                Credits = 3,
                DepartmentID = dept.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("big.png");
            mockFile.Setup(f => f.Length).Returns(10 * 1024 * 1024); // 10MB

            var result = _controller.Create(course, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        #endregion

        #region Edit GET

        [Fact]
        public void Edit_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Edit(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Edit_Get_NotFound_ReturnsNotFound()
        {
            var result = _controller.Edit(9999);

            Assert.IsType<NotFoundResult>(result);
        }

        [Fact]
        public void Edit_Get_ValidId_ReturnsViewWithCourse()
        {
            var course = SeedCourse("Editable", 3, 4001);

            var result = _controller.Edit(4001) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Editable", model.Title);
        }

        #endregion

        #region Edit POST

        [Fact]
        public void Edit_Post_ValidCourse_RedirectsToIndex()
        {
            var course = SeedCourse("Original", 3, 5001);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Course
            {
                CourseID = 5001,
                Title = "Updated",
                Credits = 4,
                DepartmentID = course.DepartmentID
            };

            var result = _controller.Edit(updated, null);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
        }

        [Fact]
        public void Edit_Post_InvalidFileExtension_ReturnsViewWithError()
        {
            var course = SeedCourse("Edit", 3, 5002);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Course
            {
                CourseID = 5002,
                Title = "Edit",
                Credits = 3,
                DepartmentID = course.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("virus.bat");
            mockFile.Setup(f => f.Length).Returns(100);

            var result = _controller.Edit(updated, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_FileTooLarge_ReturnsViewWithError()
        {
            var course = SeedCourse("Edit", 3, 5003);
            _context.Entry(course).State = Microsoft.EntityFrameworkCore.EntityState.Detached;

            var updated = new Course
            {
                CourseID = 5003,
                Title = "Edit",
                Credits = 3,
                DepartmentID = course.DepartmentID
            };

            var mockFile = new Mock<IFormFile>();
            mockFile.Setup(f => f.FileName).Returns("huge.png");
            mockFile.Setup(f => f.Length).Returns(6 * 1024 * 1024);

            var result = _controller.Edit(updated, mockFile.Object) as ViewResult;

            Assert.NotNull(result);
            Assert.True(_controller.ModelState.ContainsKey("teachingMaterialImage"));
        }

        [Fact]
        public void Edit_Post_InvalidModelState_ReturnsView()
        {
            _controller.ModelState.AddModelError("Title", "Required");
            var course = new Course { CourseID = 5004, Title = "X" };

            var result = _controller.Edit(course, null) as ViewResult;

            Assert.NotNull(result);
        }

        #endregion

        #region Delete GET

        [Fact]
        public void Delete_Get_NullId_ReturnsBadRequest()
        {
            var result = _controller.Delete(null);

            var statusResult = Assert.IsType<StatusCodeResult>(result);
            Assert.Equal(400, statusResult.StatusCode);
        }

        [Fact]
        public void Delete_Get_ValidId_ReturnsViewWithCourse()
        {
            var course = SeedCourse("Deletable", 3, 6001);

            var result = _controller.Delete(6001) as ViewResult;

            Assert.NotNull(result);
            var model = Assert.IsType<Course>(result.Model);
            Assert.Equal("Deletable", model.Title);
        }

        #endregion

        #region DeleteConfirmed

        [Fact]
        public void DeleteConfirmed_ValidId_RemovesAndRedirects()
        {
            var course = SeedCourse("ToDelete", 3, 7001);

            var result = _controller.DeleteConfirmed(7001);

            var redirect = Assert.IsType<RedirectToActionResult>(result);
            Assert.Equal("Index", redirect.ActionName);
            Assert.Null(_context.Courses.Find(7001));
        }

        #endregion
    }
}

using ContosoUniversity.Controllers;
using ContosoUniversity.Data;
using ContosoUniversity.Models;
